-- Schema-only normalized evidence; no Auth, profile or business records.
select jsonb_build_object('functions',(select jsonb_agg(to_jsonb(t) order by t.signature) from (select p.oid::regprocedure::text signature,n.nspname as schema,p.proname as name,pg_get_functiondef(p.oid) definition,md5(pg_get_functiondef(p.oid)) definition_md5,md5(p.prosrc) body_md5,pg_get_userbyid(p.proowner) owner,p.proacl::text acl,p.prosecdef,p.proconfig,p.provolatile,p.proparallel,p.proisstrict,p.proleakproof from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private','team_private','team_attendance_private','notifications_private','finance_private','pit_private','planning_private','planning_goals_private','planning_review_private','fabrication_private','outreach_private','volunteer_private') and not exists(select 1 from pg_depend d where d.objid=p.oid and d.classid='pg_proc'::regclass and d.deptype='e')) t),'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname not in ('realtime','auth')),'constraints',(select jsonb_agg(jsonb_build_object('relation',conrelid::regclass::text,'conname',conname,'definition',pg_get_constraintdef(oid)) order by conrelid::regclass::text,conname) from pg_constraint where conrelid in ('public.profiles'::regclass,'team_private.invitations'::regclass) and contype='c'));
